import{_ as i}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as o,a,b as r,c as t,d as s,e as n,f as l,g as m,h as p,i as c,j as d,k as u,l as g,m as h,n as v,o as f,p as b,q as _}from"./chunks/3DM-CU.Cv4Q9_Tx.js";import{_ as z,o as q,c as x,a3 as k}from"./chunks/framework.g9mfNVRQ.js";const L=JSON.parse('{"title":"Menu 3 punti","description":"","frontmatter":{"source_hash":"f83c7ecdbb","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/use/3dotsmenu.md","filePath":"it/use/3dotsmenu.md"}'),P={name:"it/use/3dotsmenu.md"};function y(S,e,D,I,w,M){return q(),x("div",null,[...e[0]||(e[0]=[k('<img src="'+i+'" style="zoom:75%;"><h3 id="reminders" tabindex="-1">Promemoria <a class="header-anchor" href="#reminders" aria-label="Permalink to &quot;Promemoria {#reminders}&quot;">​</a></h3><p>Con questo menu puoi impostare vari promemoria: tocca semplicemente il pulsante + in basso a destra.</p><img src="'+o+'" style="zoom:75%;"><p>Dagli il nome che preferisci</p><img src="'+a+'" style="zoom:75%;"><p>L&#39;icona della nota musicale <code>1</code> ti permette di scegliere il suono che verrà riprodotto quando il promemoria si attiva.<br> Puoi impostare il promemoria perché scatti dopo un certo intervallo da adesso, usando la selezione <code>2</code> ore, giorni, settimane e il valore numerico. Se imposti Ripetere, si ripeterà con lo stesso intervallo: ad esempio puoi farlo suonare ogni 2 settimane.<br> Puoi impostarlo perché scatti solo nei Giorni feriali o nel Weekend, oppure in entrambi <code>3</code>.<br> Se selezioni Alternato, mostrerà messaggi diversi <code>4</code> che puoi scambiare con l&#39;icona della doppia freccia.<br> Puoi far leggere ad alta voce il promemoria quando scatta.<br> Se selezioni Solo rintocco, il promemoria non dovrà essere confermato: suonerà una volta sola. Senza questa opzione suonerà ripetutamente finché non viene chiuso.<br> Solo A Casa fa scattare il promemoria solo quando il telefono è connesso al Wi-Fi di casa: vedi sotto come impostarlo.</p><p>Attivando o disattivando le caselle vengono mostrati suggerimenti sulla funzione effettiva.</p><p>Una volta impostato, puoi cambiare il titolo del promemoria toccandolo.</p><p>Puoi modificarlo con un tocco prolungato.</p><p>Scorrendo un promemoria verso sinistra lo posticipi di 30 minuti (predefinito); puoi cambiare questo intervallo con il pulsante in basso.</p><img src="'+r+'" style="zoom:75%;"><p>Scorrendo un promemoria verso destra puoi <code>1</code> posticiparlo del tempo selezionato in basso (da 15 minuti a 1 settimana) oppure <code>3</code> eliminarlo. Se cambi idea puoi annullare le modifiche <code>2</code>.</p><img src="'+t+'" style="zoom:75%;"><p>In alto a destra è disponibile un altro menu a 3 puntini.</p><img src="'+s+'" style="zoom:75%;"><p>Puoi definire la rete di casa con Imposta Rete Domestica: viene usata quando il promemoria è impostato su Solo A Casa.<br> Puoi disattivare i promemoria durante la notte; puoi anche disattivare tutti gli avvisi, e in questo caso la casella successiva ti permette di riattivarli (riattivare tutti i promemoria) la mattina dopo.</p><h3 id="emergency-messages" tabindex="-1">Messaggi di emergenza <a class="header-anchor" href="#emergency-messages" aria-label="Permalink to &quot;Messaggi di emergenza {#emergency-messages}&quot;">​</a></h3><p>xDrip può inviare automaticamente SMS in determinate condizioni per avvisare altre persone. Ovviamente servono la copertura della rete telefonica e una SIM attiva. Per usare questa funzione, xDrip deve essere autorizzato ad accedere alla posizione del telefono.</p><img src="'+n+'" style="zoom:75%;"><p>Per configurarla devi prima aggiungere un contatto, poi eventualmente inserire un nome e infine decidere quale situazione di emergenza farà partire l&#39;SMS.</p><img src="'+l+'" style="zoom:75%;"><p>Puoi poi inviare un messaggio di prova per verificare che il sistema di emergenza funzioni correttamente.</p><img src="'+m+'" style="zoom:75%;"><h3 id="import-export-features" tabindex="-1">Import Export Features <a class="header-anchor" href="#import-export-features" aria-label="Permalink to &quot;Import Export Features {#import-export-features}&quot;">​</a></h3><p>In questo menu trovi varie opzioni per importare (solo l&#39;intero database di xDrip) o esportare i dati.</p><img src="'+p+'" style="zoom:75%;"><p>Vedi <a href="./../troubleshoot/reinstall.html#backup">qui</a> per l&#39;importazione/esportazione del database e delle impostazioni.</p><p>Puoi esportare i dati da una certa data fino a oggi, in formato SiDiary. Il file verrà salvato in <code>/storage/emulated/0/xDrip</code> come file zip contenente l&#39;elenco dei dati in valori separati da virgola.</p><img src="'+c+'" style="zoom:75%;"><h3 id="crowd-sources-translation" tabindex="-1">Traduzione Crowd-source <a class="header-anchor" href="#crowd-sources-translation" aria-label="Permalink to &quot;Traduzione Crowd-source {#crowd-sources-translation}&quot;">​</a></h3><p>La traduzione di xDrip si basa su volontari che usano <a href="https://crowdin.com/project/xdrip" target="_blank" rel="noreferrer">Crowdin</a>.<br> Il tuo contributo è benvenuto: contatta i gestori in fondo alla pagina.</p><img src="'+d+'" style="zoom:75%;"><h3 id="events-log" tabindex="-1">Registro eventi <a class="header-anchor" href="#events-log" aria-label="Permalink to &quot;Registro eventi {#events-log}&quot;">​</a></h3><p>Il registro eventi offre molte informazioni su ciò che xDrip sta facendo; puoi aggiungere altre tracce aggiungendo dei <a href="./lesscommon.html#extra-logging-settings">tag</a>.</p><img src="'+u+'" style="zoom:75%;"><p>Puoi anche filtrare gli elementi mostrati selezionando i log o gli eventi desiderati con le caselle sopra l&#39;elenco.<br> Quando condividi screenshot del log degli errori, assicurati di attivare tutto e di nascondere manualmente le informazioni personali (credenziali, numeri di serie, ...)</p><p><code>High</code> mostra gli errori</p><img src="'+g+'" style="zoom:75%;"><p><code>Mid</code> mostra le tracce</p><img src="'+h+'" style="zoom:75%;"><p><code>Low</code> mostra tutto il resto (importanza minore)</p><p><code>EH</code> mostra gli eventi di importanza maggiore</p><img src="'+v+'" style="zoom:75%;"><p><code>EL</code> mostra gli eventi di importanza minore.</p><img src="'+f+'" style="zoom:75%;"><h3 id="libre-trend" tabindex="-1">Tendenza Libre <a class="header-anchor" href="#libre-trend" aria-label="Permalink to &quot;Tendenza Libre {#libre-trend}&quot;">​</a></h3><p>Se usi un sensore Libre, Mostra tendenza Libre visualizza gli ultimi 45 minuti di informazioni del sensore, minuto per minuto.</p><img src="'+b+'" style="zoom:75%;"><h3 id="share-settings-via-qr-code" tabindex="-1">Condividi impostazioni tramite il codice QR <a class="header-anchor" href="#share-settings-via-qr-code" aria-label="Permalink to &quot;Condividi impostazioni tramite il codice QR {#share-settings-via-qr-code}&quot;">​</a></h3><p>È una scorciatoia per Menu / Impostazioni / <a href="./copysettings.html">Mostra impostazioni dei codici QR</a></p><h3 id="check-for-updated-version" tabindex="-1">Verifica versione aggiornata <a class="header-anchor" href="#check-for-updated-version" aria-label="Permalink to &quot;Verifica versione aggiornata {#check-for-updated-version}&quot;">​</a></h3><p>Questa voce avvia una verifica della versione come definito in Menu / Impostazioni / <a href="./update.html">xDrip+ Impostazioni di aggiornamento</a><br> Se è disponibile una nuova versione, si aprirà la schermata di download.</p><img src="'+_+'" style="zoom:75%;"><h3 id="send-feedback-to-developers" tabindex="-1">Invia Feedback agli sviluppatori <a class="header-anchor" href="#send-feedback-to-developers" aria-label="Permalink to &quot;Invia Feedback agli sviluppatori {#send-feedback-to-developers}&quot;">​</a></h3><p>Usa questa funzione solo per inviare complimenti.</p><p>Per altre richieste preferisci le <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">discussioni GitHub di xDrip</a> o <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">Facebook</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 15/12/2024</em></a></p>',59)])])}const R=z(P,[["render",y]]);export{L as __pageData,R as default};
